({t, T, s, i, R, api}) => {
  const {seg, cl, io, out, back, esc, punch, at, boomFx} = api;
  if (!s || s.kind === 'big' || s.kind === 'outro') return '';
  const S = (R && R.scenes) || [];
  const GR = '#8fe01f', GD = '#13220a', SV = '#dfe6ee', LE = '#171a21', RD = '#ff4d5a', AM = '#ffb347', MU = '#8b9a8f', SK = '#f0c8a0', TL = '#5be3c0', PA = '#f4f1e6', LN = '#24402c';
  const A = (k, w) => { const q = S[k]; if (!q) return null; let v = null; try { v = at(q, w); } catch (e) { v = null; } return (typeof v === 'number' && isFinite(v) && v > (q.vs || 0) + .01) ? v : null; };
  const P = (x, dd) => (x == null ? null : x + dd);
  const F = (...v) => { for (const x of v) if (typeof x === 'number' && isFinite(x) && x < 1e8) return x; return 1e9; };
  const T0 = k => (S[k] && typeof S[k].t0 === 'number' ? S[k].t0 : 1e9);
  const VS = k => (S[k] && typeof S[k].vs === 'number' ? S[k].vs : T0(k));
  const f1 = x => (Math.round(x * 10) / 10).toString();
  const pop = (a, d) => back(seg(t, a, a + (d || .35)));

  // ---- when things happen (each on its spoken word)
  const tOut = VS(0) - .05, t4 = tOut + .9;                       // the hook: four flips of the calendar inside the first second
  const flips = [0, 1, 2, 3].map(k => tOut + (t4 - tOut) * k / 3);
  const tEnd = F(A(0, 'end'), t4 + .6), t33 = Math.max(F(A(0, '33'), tEnd + 1), t4 + 1), tNv = F(A(0, 'Nvidia'), t33 + .8);
  const tAdm = F(A(1, 'admitted'), P(VS(1), 1));
  const tWed = F(A(1, 'Wednesday'), tAdm + 1.5), tRep = Math.max(F(A(1, 'reported a second'), A(1, 'reported'), tWed + 1.2), tWed + .3);
  const tExe = F(A(1, 'executive'), tRep + 1.2);
  const tBoard = F(A(2, 'board investigating'), A(2, 'board'), VS(2)), tThu = F(A(2, 'Thursday'), tBoard + 1.2);
  const tStep = Math.max(F(A(2, 'stepped down'), A(2, 'stepped'), tThu + .6), tThu + .2), tLeft = Math.max(F(A(2, 'left the board'), tStep + 1.8), tStep + 1.2);
  const tFell = F(A(3, 'fell'), P(VS(3), .5)), t13 = Math.max(F(A(3, '13%'), A(3, '13'), tFell + .5), tFell + .2);
  const t400 = F(A(3, '400'), t13 + 1.2), tBack = F(A(3, 'won back'), A(3, 'back'), t400 + 1.6);
  const tNo = F(A(4, 'No chart'), VS(4)), tMove = F(A(4, 'your move'), A(4, 'move'), tNo + 1.4);
  const tSell = F(A(4, 'sell'), tMove + 1.6), tHold = Math.max(F(A(4, 'hold'), tSell + .6), tSell + .3);
  const tMS = F(A(5, 'Meme Street'), VS(5)), t180 = F(A(5, '180'), tMS + .8), tMade = F(A(5, 'made-up'), t180 + .4);
  const tBoss = F(A(5, 'bosses'), tMade + .9), tHit = F(A(5, 'news hits'), A(5, 'hits'), tBoss + 1.2);
  const tPr = F(A(6, 'Practise'), VS(6)), t1k = F(A(6, '1,000'), tPr + 1), tNC = F(A(6, 'no cash value'), t1k + 1.6);
  const tHit2 = tPr + .25;

  // ---- the shake of every impact
  let sh = 0;
  for (const c of [...flips, tAdm, tRep, tFell, tHit, tHit2]) { const u = t - c; if (u >= 0 && u < .32) sh += 6 * Math.sin(u * 62) * (1 - u / .32); }

  // ---- the tower: 11 blocks, 3 years each; its height is the company's value
  const TX = 600, BY = 1235, BW = 280, BH = 34, N = 11, MS = 1.15, RX = 762;
  const hv = N - 1.5 * out(seg(t, tFell, tFell + .45)) + 1 * io(seg(t, tBack, tBack + .8));
  const topY = BY - hv * BH, TOP = BY - N * BH;
  const nFl = i === 0 ? flips.filter(c => t >= c).length : 0;
  const lean = i === 0 ? -2 * nFl * (1 - seg(t, t4 + .15, t4 + .7)) : (i === 1 ? Math.sin(t * 3.1) * (.5 * (t >= tAdm) + .7 * (t >= tRep)) : 0);
  const sink = i >= 5 ? io(seg(t, T0(5), T0(5) + .5)) : 0;

  const man = (x, y, sc, o) => {
    const col = o.jacket ? LE : '#f4f6f8';
    const arm = (sd, ang) => { const a = ang * Math.PI / 180, sx = sd * 46, sy = -196, ex = sx + sd * Math.sin(a) * 92, ey = sy + Math.cos(a) * 92;
      return `<line x1="${sx}" y1="${sy}" x2="${f1(ex)}" y2="${f1(ey)}" stroke="${SV}" stroke-width="30" stroke-linecap="round"/><line x1="${sx}" y1="${sy}" x2="${f1(ex)}" y2="${f1(ey)}" stroke="${col}" stroke-width="22" stroke-linecap="round"/><circle cx="${f1(ex)}" cy="${f1(ey)}" r="12" fill="${SK}"/>`; };
    const lg = o.leg || 0;
    let m = `<g transform="translate(${f1(x)} ${f1(y)}) rotate(${f1(o.rot || 0)}) scale(${sc})" opacity="${cl(o.al == null ? 1 : o.al, 0, 1).toFixed(2)}">`;
    for (const sd of [-1, 1]) { const fx = sd * 26 + sd * lg; m += `<line x1="${sd * 20}" y1="-100" x2="${f1(fx)}" y2="-8" stroke="${SV}" stroke-width="24" stroke-linecap="round"/><line x1="${sd * 20}" y1="-100" x2="${f1(fx)}" y2="-8" stroke="#2b303a" stroke-width="17" stroke-linecap="round"/>`; }
    m += arm(-1, o.la == null ? 16 : o.la) + arm(1, o.ra == null ? 16 : o.ra);
    m += `<path d="M-52,-206 L52,-206 L44,-96 L-44,-96 Z" fill="${col}" stroke="${SV}" stroke-width="4" stroke-linejoin="round"/>`;
    if (o.jacket) m += `<path d="M-20,-206 L0,-168 L20,-206" fill="none" stroke="${SV}" stroke-width="4"/><line x1="0" y1="-168" x2="0" y2="-100" stroke="${SV}" stroke-width="3" stroke-dasharray="7 5"/><path d="M-34,-206 L-16,-228 L-6,-204 Z M34,-206 L16,-228 L6,-204 Z" fill="${LE}" stroke="${SV}" stroke-width="3"/>`;
    m += `<circle cx="0" cy="-252" r="40" fill="${SK}" stroke="#b98b62" stroke-width="3"/>`;
    m += `<path d="M-41,-260 Q-40,-306 0,-302 Q44,-300 41,-256 Q22,-284 -8,-282 Q-30,-280 -41,-260 Z" fill="#eef2f6" stroke="#b9c2cc" stroke-width="3"/>`;
    m += `<rect x="-31" y="-262" width="25" height="19" rx="5" fill="#ffffff" fill-opacity=".25" stroke="#1a1d24" stroke-width="4"/><rect x="6" y="-262" width="25" height="19" rx="5" fill="#ffffff" fill-opacity=".25" stroke="#1a1d24" stroke-width="4"/><line x1="-6" y1="-254" x2="6" y2="-254" stroke="#1a1d24" stroke-width="4"/>`;
    m += o.mood === 'shock' ? `<circle cx="0" cy="-228" r="8" fill="#5a2a22"/>` : o.mood === 'worry' ? `<path d="M-11,-225 Q0,-235 11,-225" fill="none" stroke="#5a2a22" stroke-width="4" stroke-linecap="round"/>` : `<path d="M-13,-233 Q0,-220 13,-233" fill="none" stroke="#5a2a22" stroke-width="4" stroke-linecap="round"/>`;
    return m + `</g>`;
  };
  const coat = (x, y, sc, rot) => `<g transform="translate(${f1(x)} ${f1(y)}) rotate(${f1(rot)}) scale(${sc})">` +
    `<line x1="-46" y1="-100" x2="-62" y2="-14" stroke="${SV}" stroke-width="30" stroke-linecap="round"/><line x1="-46" y1="-100" x2="-62" y2="-14" stroke="${LE}" stroke-width="22" stroke-linecap="round"/>` +
    `<line x1="46" y1="-100" x2="62" y2="-14" stroke="${SV}" stroke-width="30" stroke-linecap="round"/><line x1="46" y1="-100" x2="62" y2="-14" stroke="${LE}" stroke-width="22" stroke-linecap="round"/>` +
    `<path d="M-52,-110 L52,-110 L44,0 L-44,0 Z" fill="${LE}" stroke="${SV}" stroke-width="4" stroke-linejoin="round"/><path d="M-20,-110 L0,-72 L20,-110" fill="none" stroke="${SV}" stroke-width="4"/>` +
    `<line x1="0" y1="-72" x2="0" y2="-4" stroke="${SV}" stroke-width="3" stroke-dasharray="7 5"/><path d="M-34,-110 L-16,-132 L-6,-108 Z M34,-110 L16,-132 L6,-108 Z" fill="${LE}" stroke="${SV}" stroke-width="3"/></g>`;
  const tag = (x, y, txt, col, t0, size, anchor) => { if (t < t0) return ''; const sz = size || 34, w = txt.length * sz * .63 + 36, k = pop(t0, .3), ox = anchor === 'middle' ? -w / 2 : 0;
    return `<g transform="translate(${f1(x)} ${f1(y)}) scale(${k.toFixed(3)})"><rect x="${f1(ox)}" y="${-sz}" width="${f1(w)}" height="${f1(sz * 1.5)}" rx="12" fill="#0a140d" stroke="${col}" stroke-width="3"/><text x="${f1(ox + w / 2)}" y="${f1(sz * .1)}" text-anchor="middle" font-size="${sz}" font-weight="800" fill="${col}">${esc(txt)}</text></g>`; };
  const cal = (x, y, head, big, small, tf) => { const k = .25 + .75 * pop(tf, .28);
    return `<g transform="translate(${f1(x)} ${f1(y)}) scale(1 ${k.toFixed(3)})"><rect x="0" y="0" width="220" height="250" rx="18" fill="${PA}" stroke="#c9c2a8" stroke-width="3"/><path d="M0,66 L0,18 Q0,0 18,0 L202,0 Q220,0 220,18 L220,66 Z" fill="${RD}"/>` +
      `<text x="110" y="47" text-anchor="middle" font-size="38" font-weight="800" fill="#fff">${esc(head)}</text><text x="110" y="${small ? 172 : 190}" text-anchor="middle" font-size="${small ? 104 : 120}" font-weight="800" fill="#1a1d24">${esc(big)}</text>` +
      (small ? `<text x="110" y="226" text-anchor="middle" font-size="30" font-weight="700" fill="#5a5f6a">${esc(small)}</text>` : '') + `</g>`; };

  let w = `<line x1="40" x2="1040" y1="${BY + 3}" y2="${BY + 3}" stroke="${LN}" stroke-width="4"/>`;
  for (let k = 0; k < 7; k++) { const yy = BY - ((t * 46 + k * 97) % 640), xx = 120 + ((k * 331) % 840); w += `<rect x="${xx}" y="${f1(yy)}" width="7" height="7" fill="${GR}" opacity="${(.12 + .16 * Math.sin(t * 2 + k)).toFixed(2)}"/>`; }

  // ---- the big tower and what stands on it
  if (sink < 1) {
    let g = `<g transform="translate(${TX} ${BY}) scale(${(1 - .85 * sink).toFixed(3)}) translate(${-TX} ${-BY}) rotate(${f1(lean)} ${TX} ${BY})" opacity="${(1 - sink).toFixed(2)}">`;
    for (let k = 0; k < Math.ceil(hv - .01); k++) { const hk = Math.min(1, hv - k), y = BY - (k + hk) * BH, fl = i === 0 ? Math.sin(Math.PI * seg(t, t33 + k * .05, t33 + k * .05 + .35)) : 0;
      g += `<rect x="${TX - BW / 2}" y="${f1(y + 3)}" width="${BW}" height="${f1(Math.max(4, hk * BH - 6))}" rx="6" fill="${fl > .05 ? '#3d6a16' : GD}" stroke="${GR}" stroke-width="3"/>`;
      if (hk > .6) g += `<line x1="${TX - BW / 2 - 14}" x2="${TX - BW / 2}" y1="${f1(y + BH / 2)}" y2="${f1(y + BH / 2)}" stroke="${GR}" stroke-width="5"/><line x1="${TX + BW / 2}" x2="${TX + BW / 2 + 14}" y1="${f1(y + BH / 2)}" y2="${f1(y + BH / 2)}" stroke="${GR}" stroke-width="5"/>`; }
    const crack = (pts, col, t0) => { if (t < t0) return ''; const u = out(seg(t, t0, t0 + .45));
      return `<polyline points="${pts.map(p => (TX + p[0]) + ',' + f1(TOP + p[1])).join(' ')}" fill="none" stroke="${col}" stroke-width="8" stroke-linejoin="round" stroke-dasharray="330" stroke-dashoffset="${f1(330 * (1 - u))}"/>`; };
    if (i >= 1 && i <= 2) g += crack([[-56, 0], [-84, 46], [-44, 92], [-78, 140], [-50, 192], [-70, 244]], AM, tAdm) + crack([[54, 0], [84, 42], [46, 88], [80, 132], [42, 184], [72, 236]], RD, tRep);
    // the man: on top in his jacket, thrown off inside the first second, back for the real four days, then he takes the steps
    const fy = topY, wob = i === 1 ? Math.sin(t * 5.2) * (2 * (t >= tAdm) + 4 * (t >= tRep)) : 0;
    if (i === 0 && t < t4) g += man(TX, fy, MS, {jacket: 1, la: nFl < 2 ? 150 + 8 * Math.sin(t * 9) : 70, ra: nFl < 2 ? 150 - 8 * Math.sin(t * 9) : 70, rot: 4 * nFl * Math.sin(t * 30), mood: nFl < 2 ? 'proud' : 'shock'});
    if (i === 1) { const d = pop(T0(1), .45); g += man(TX, fy - 300 * (1 - d), MS, {jacket: 1, la: t >= tRep ? 120 : t >= tAdm ? 70 : 16, ra: t >= tRep ? 120 : t >= tAdm ? 30 : 16, rot: wob, mood: t >= tAdm ? 'worry' : 'proud', al: seg(t, T0(1), T0(1) + .15)}); }
    if (i === 2 && t < tStep) g += man(TX, fy, MS, {jacket: 1, la: 30, ra: 30, rot: Math.sin(t * 5) * 2, mood: 'worry'});
    const coatOn = (i === 0 && t >= t4) || (i === 2 && t >= tStep) || i === 3 || i === 4 || i === 5;
    if (coatOn) { const c0 = i === 0 ? t4 : i === 2 ? tStep : -9, hop = 70 * Math.sin(Math.PI * seg(t, c0, c0 + .55)); g += coat(TX, fy - hop, MS, Math.sin(t * 1.7) * 2.5 + (i === 3 ? 14 * (1 - seg(t, tFell, tFell + .7)) * (t >= tFell) : 0)); }
    if (i === 3 || i === 4) {   // what the fall took: the missing top, drawn as a ghost
      const lost = N - hv, a4 = i === 4 ? 1 - seg(t, T0(4), T0(4) + .3) : 1;
      if (t >= tFell && lost > .05) g += `<rect x="${TX - BW / 2}" y="${f1(TOP + 3)}" width="${BW}" height="${f1(lost * BH - 6)}" rx="6" fill="${RD}" fill-opacity=".14" stroke="${RD}" stroke-width="3" stroke-dasharray="10 8"/>`;
      for (let k = 0; k < 7; k++) { const u = seg(t, tFell, tFell + .9); if (u <= 0 || u >= 1) continue; const dx = (k - 3) * 80 * u, dy = -120 * u + 520 * u * u;
        g += `<rect x="${f1(TX + dx - 14)}" y="${f1(TOP + 20 + dy)}" width="28" height="20" fill="${RD}" opacity="${(1 - u).toFixed(2)}" transform="rotate(${f1(k * 50 + u * 300)} ${f1(TX + dx)} ${f1(TOP + 30 + dy)})"/>`; }
      if (a4 > 0) g += `<g opacity="${a4.toFixed(2)}">` + (t >= t13 ? `<g transform="translate(${RX} 800) scale(${pop(t13, .3).toFixed(3)})"><text x="0" y="0" font-size="84" font-weight="800" fill="${RD}">-13%</text><text x="0" y="44" font-size="30" font-weight="700" fill="${MU}">EARLY TRADING</text></g>` : '') + tag(RX, 930, 'HALF BACK', GR, tBack, 36) + `</g>`;
    }
    if (i === 0) g += tag(RX, 800, '~$4 TRILLION', GR, tNv, 32);
    if (i === 2 || i === 3) {   // "stepped down": six steps appear on the tower's side and he takes them, leaving the jacket
      const ST = 6, shh = (BY - topY) / ST, a3 = i === 3 ? 1 - seg(t, T0(3), T0(3) + .3) : 1;
      const slip = out(seg(t, tStep, tStep + .18)), pos = k => k < 0 ? [TX - 40 - 80 * slip, topY] : [TX - BW / 2 - (k + 1) * 50 + 25, topY + (k + 1) * shh];
      if (a3 > 0) for (let k = 0; k < ST; k++) { const u = pop(tStep - .3 + k * .06, .3); if (u <= 0) continue; const q = pos(k);
        g += `<rect x="${f1(q[0] - 25)}" y="${f1(q[1])}" width="${f1(50 * Math.min(1, u))}" height="12" rx="4" fill="${GR}" opacity="${a3.toFixed(2)}"/>`; }
      if (i === 2 && t >= tStep) { const p = seg(t, tStep + .18, tStep + 1.9) * ST, k = Math.min(ST - 1, Math.floor(p)), fr = Math.min(1, p - k), a = pos(k - 1), b = pos(k), away = seg(t, tStep + 1.9, tStep + 2.9);
        const x = a[0] + (b[0] - a[0]) * fr - 440 * away, y = a[1] + (b[1] - a[1]) * fr - 34 * Math.sin(Math.PI * fr);
        if (away < 1) g += man(x, y, MS, {jacket: 0, la: 26 + 20 * Math.sin(t * 9), ra: 26 - 20 * Math.sin(t * 9), leg: 8 * Math.sin(t * 9), mood: 'worry', al: 1 - seg(t, tStep + 2.6, tStep + 2.9)}); }
    }
    g += `</g>`;
    if (i === 0 && t >= t4) { const u = seg(t, t4, t4 + 1.1); if (u < 1) g += man(TX - 430 * u, topY - 620 * u + 1500 * u * u, MS, {jacket: 0, la: 150, ra: 150, rot: -420 * u, mood: 'shock', al: 1 - seg(t, t4 + .7, t4 + .95)}) + boomFx(TX, topY - 150, seg(t, t4, t4 + .5), 170, RD); }
    w += g;
  }

  // ---- the calendar: four days in the hook, then the real dates
  if (i <= 4) {
    const off = i === 4 ? -360 * io(seg(t, T0(4), T0(4) + .4)) : 0;
    let c = null;
    if (i === 0) c = nFl ? ['DAY', String(nFl), '', flips[nFl - 1]] : ['DAY', '0', '', -9];
    else if (i === 1) c = t >= tWed ? ['WED', '11', 'NOV 2026', tWed] : ['SUN', '8', 'NOV 2026', T0(1)];
    else c = (i === 2 && t < tThu) ? ['WED', '11', 'NOV 2026', -9] : ['THU', '12', 'NOV 2026', i === 2 ? tThu : -9];
    if (c && off > -350) w += cal(60 + off, 540, c[0], c[1], c[2], c[3]);
  }
  if (i === 1) w += tag(RX, 770, 'ADMITTED', AM, tAdm, 36) + tag(RX, 855, 'REPORTED', RD, tRep, 36) + (t >= tExe ? `<text x="${RX}" y="912" font-size="28" font-weight="700" fill="${MU}" opacity="${seg(t, tExe, tExe + .3).toFixed(2)}">BY THE NY TIMES</text>` : '');
  if (i === 2) w += tag(RX, 800, 'BOARD PROBE', AM, tBoard, 30) + tag(RX, 890, 'OFF THE BOARD', RD, tLeft, 28);

  // ---- the viewer's move
  if (i === 4) {
    const cu = out(seg(t, tNo, tNo + .7)), gp = out(seg(t, tNo + .75, tNo + 1.05));
    w += `<g transform="translate(36 1200) scale(.88) translate(-60 -1200)"><rect x="60" y="880" width="390" height="320" rx="16" fill="#0a140d" stroke="${LN}" stroke-width="3"/>`;
    w += `<polyline points="90,1120 130,1098 165,1108 205,1072 245,1084 285,1046 330,1030" fill="none" stroke="${GR}" stroke-width="7" stroke-linejoin="round" stroke-linecap="round" stroke-dasharray="280" stroke-dashoffset="${f1(280 * (1 - cu))}"/>`;
    if (gp > 0) w += `<line x1="330" y1="1030" x2="330" y2="${f1(1030 + 110 * gp)}" stroke="${RD}" stroke-width="7" stroke-dasharray="9 7"/><polyline points="330,${f1(1030 + 110 * gp)} 372,${f1(1042 + 110 * gp)} 420,${f1(1020 + 110 * gp)}" fill="none" stroke="${RD}" stroke-width="7" stroke-linejoin="round" stroke-linecap="round"/>`;
    if (t >= tNo + .9) w += `<text x="255" y="950" text-anchor="middle" font-size="36" font-weight="800" fill="${SV}" opacity="${seg(t, tNo + .9, tNo + 1.2).toFixed(2)}">NO WARNING</text>`;
    w += `</g>`;
    if (t >= tMove) w += `<g transform="translate(${TX} ${f1(topY - 185)}) rotate(${f1(8 * Math.sin(t * 4))}) scale(${(pop(tMove, .35) * (1 + .08 * Math.sin(t * 7))).toFixed(3)})"><text x="0" y="0" text-anchor="middle" font-size="130" font-weight="800" fill="${TL}">?</text></g>`;
    const btn = (x, txt, col, t0, ph) => { if (t < t0) return ''; const k = pop(t0, .3) * (1 + .06 * Math.sin(t * 6 + ph));
      return `<g transform="translate(${x} 690) scale(${k.toFixed(3)})"><rect x="-118" y="-62" width="236" height="124" rx="22" fill="${col}"/><text x="0" y="19" text-anchor="middle" font-size="56" font-weight="800" fill="#08110b">${txt}</text></g>`; };
    w += btn(188, 'SELL', RD, tSell, 0) + btn(884, 'HOLD', GR, tHold, 3.14);
  }

  // ---- Meme Street: a street of made-up companies, each with its own boss, and the news hits them too
  if (i >= 5) {
    const XS = [110, 230, 350, 470, 590, 710, 830, 950], HS = [250, 300, 210, 340, 290, 230, 320, 270], CO = [TL, AM, GR, '#ff8fd0', TL, AM, GR, '#b9a2ff'];
    for (let k = 0; k < 8; k++) {
      const u = out(seg(t, tMS + k * .07, tMS + k * .07 + .5)); if (u <= 0) continue;
      const d1 = k === 2 ? .4 * out(seg(t, tHit, tHit + .4)) : 0, d2 = k === 4 ? .36 * out(seg(t, tHit2, tHit2 + .4)) : 0, up = k === 5 ? .26 * io(seg(t, tHit + .7, tHit + 1.2)) : 0;
      const hh = HS[k] * u * (1 - d1 - d2 + up), y = BY - hh, hot = (d1 > .02 || d2 > .02), col = hot ? RD : up > .02 ? GR : '#4f8f5e';
      w += `<rect x="${XS[k] - 44}" y="${f1(y)}" width="88" height="${f1(hh)}" rx="6" fill="${hot ? '#3a1218' : up > .02 ? '#1c3a12' : '#12301c'}" stroke="${col}" stroke-width="4"/>`;
      const bu = pop(tBoss + k * .05, .3); if (bu > 0) { const jy = hot ? -18 * Math.abs(Math.sin(t * 11)) : 0;
        w += `<g transform="translate(${XS[k]} ${f1(y + jy)}) scale(${(1.45 * bu).toFixed(3)})"><line x1="0" y1="-4" x2="0" y2="-40" stroke="${CO[k]}" stroke-width="7" stroke-linecap="round"/><line x1="-16" y1="${hot ? -44 : -22}" x2="16" y2="${hot ? -44 : -22}" stroke="${CO[k]}" stroke-width="6" stroke-linecap="round"/><circle cx="0" cy="-54" r="14" fill="${CO[k]}"/></g>`; }
    }
    const bolt = (x, t0, hgt) => { const u = seg(t, t0 - .12, t0 + .5); if (u <= 0 || u >= 1) return ''; const y1 = BY - hgt - 100;
      return `<polyline points="${x + 40},540 ${x - 16},${f1(540 + (y1 - 540) * .45)} ${x + 22},${f1(540 + (y1 - 540) * .55)} ${x},${f1(y1)}" fill="none" stroke="#ffe45c" stroke-width="12" stroke-linejoin="round" opacity="${(1 - u).toFixed(2)}"/>` + boomFx(x, y1 + 40, seg(t, t0, t0 + .45), 100, RD); };
    w += bolt(350, tHit, 210) + bolt(590, tHit2, 290);
    if (i === 5) w += tag(540, 620, 'ALL MADE-UP', AM, tMade, 42, 'middle');
    if (i === 6) {
      const k1 = pop(tPr + .5, .3), k2 = pop(tPr + .7, .3), pk = io(seg(t, t1k + .5, t1k + .9)), ck = t >= t1k + .9 ? 1 + .14 * Math.sin(Math.PI * seg(t, t1k + .9, t1k + 1.2)) : 1;
      if (k1 > 0) w += `<g transform="translate(400 610) scale(${k1.toFixed(3)})"><rect x="-100" y="-50" width="200" height="100" rx="18" fill="${RD}"/><text x="0" y="16" text-anchor="middle" font-size="46" font-weight="800" fill="#08110b">SELL</text></g>`;
      if (k2 > 0) w += `<g transform="translate(680 610) scale(${(k2 * ck).toFixed(3)})"><rect x="-100" y="-50" width="200" height="100" rx="18" fill="${GR}"/><text x="0" y="16" text-anchor="middle" font-size="46" font-weight="800" fill="#08110b">HOLD</text></g>`;
      if (t >= t1k + .3) { const cx = 300 + (770 - 300) * pk, cy = 780 + (668 - 780) * pk; w += `<circle cx="${f1(cx)}" cy="${f1(cy)}" r="${f1(20 + 14 * Math.sin(Math.PI * seg(t, t1k + .9, t1k + 1.25)))}" fill="none" stroke="${TL}" stroke-width="6"/><circle cx="${f1(cx)}" cy="${f1(cy)}" r="6" fill="${TL}"/>`; }
      w += tag(540, 745, 'NO CASH VALUE', AM, tNC, 34, 'middle');
    }
  }

  // ---- the HUD: who he is now, the years, and the day count / the money
  const L = [[-1e9, 'CEO', SV], [flips[1], 'IN TROUBLE', AM], [t4, 'OUT', RD], [T0(1), 'CEO', SV], [tAdm, 'UNDER FIRE', AM], [tStep, 'STEPS DOWN', RD], [tLeft, 'OUT', RD], [T0(3), 'INTERIM CEO', AM], [tMove, 'YOUR MOVE', TL], [tMS, 'MEME STREET', TL], [tPr, 'YOUR TURN', GR]];
  L.sort((a, b) => a[0] - b[0]);
  let cur = L[0]; for (const e of L) if (e[0] <= t) cur = e;
  let h = `<text x="90" y="418" font-size="28" font-weight="700" fill="${MU}" letter-spacing="2">STATUS</text>`;
  h += `<g transform="translate(90 484) scale(${(.85 + .15 * pop(cur[0], .3)).toFixed(3)})"><text x="0" y="0" font-size="44" font-weight="800" fill="${cur[2]}">${esc(cur[1])}</text></g>`;
  let ml = 'YEARS', mv = '33', mc = GR, mt = -1e9;
  if (i === 0) { if (t < t33) { ml = 'SINCE'; mv = '1993'; mc = SV; } else { const u = seg(t, t33, t33 + .6); mv = String(Math.round(33 * io(u))); mc = u < 1 ? SV : GR; mt = t33 + .6; } }
  if (i >= 5) { ml = 'COMPANIES'; const u = seg(t, t180, t180 + .5); mv = t < t180 ? '0' : u < 1 ? String(Math.round(180 * io(u))) : '180+'; mc = TL; mt = t180; }
  h += `<text x="540" y="418" text-anchor="middle" font-size="28" font-weight="700" fill="${MU}" letter-spacing="2">${ml}</text>`;
  h += `<g transform="translate(540 486) scale(${(.85 + .15 * pop(mt, .3)).toFixed(3)})"><text x="0" y="0" text-anchor="middle" font-size="56" font-weight="800" fill="${mc}">${esc(mv)}</text></g>`;
  let rl = 'DAYS', rv = '0', rc = SV, rt = -1e9;
  if (i === 0) { rv = String(nFl); if (nFl) { rc = nFl === 4 ? RD : AM; rt = flips[nFl - 1]; } }
  else if (i === 1) { if (t >= tWed) { rv = '3'; rc = AM; rt = tWed; } }
  else if (i === 2) { rv = t >= tThu ? '4' : '3'; rc = t >= tThu ? RD : AM; rt = t >= tThu ? tThu : -1e9; }
  else if (i === 3 || i === 4) { rl = 'WIPED'; const u = seg(t, t400, t400 + .8); rv = t < t400 ? '$0' : u < 1 ? '$' + Math.round(400 * io(u)) + 'B' : '$400B+'; rc = t >= t400 ? RD : SV; rt = t400; }
  else if (i === 5) { rl = 'NEWS'; rv = t >= tHit ? 'HITS' : 'LIVE'; rc = t >= tHit ? RD : TL; rt = t >= tHit ? tHit : -1e9; }
  else { rl = 'PRACTICE'; const u = seg(t, t1k, t1k + .7); rv = t < t1k ? '0 MB' : u < 1 ? Math.round(1000 * io(u)) + ' MB' : '1,000 MB'; rc = GR; rt = t1k; }
  h += `<text x="990" y="418" text-anchor="end" font-size="28" font-weight="700" fill="${MU}" letter-spacing="2">${rl}</text>`;
  h += `<g transform="translate(990 486) scale(${(.85 + .15 * pop(rt, .3)).toFixed(3)})"><text x="0" y="0" text-anchor="end" font-size="56" font-weight="800" fill="${rc}">${esc(rv)}</text></g>`;

  return `<svg style="position:absolute;left:0;top:0" width="1080" height="1920"><g transform="translate(${f1(sh)} ${f1(sh * .6)})">${w}</g>${h}</svg>` + punch(s, t);
}
